## Why This Is Asked
This question tests CGO callback ergonomics, memory ownership across language boundaries, and safe concurrent usage of a streaming C API.

## Key Concepts
- **CGO callback mechanism**: Passing Go functions to C for asynchronous callbacks requires exporting Go functions and using `runtime/cgo` for proper handling
- **Memory ownership**: The C side allocates with `malloc`; Go must free it after copying to avoid memory leaks
- **Concurrency**: Per-stream context with proper synchronization ensures multiple simultaneous streams operate correctly
- **Error propagation**: Status codes passed through the callback indicate success or failure conditions that must be communicated back to Go

## Code Example

**header.csv_stream.h:**
```c
#ifndef CSV_STREAM_H
#define CSV_STREAM_H

#include <stddef.h>

typedef void (*csv_stream_callback)(const char* json, size_t len, int status, void* ctx);

int csv_stream(const char* path, csv_stream_callback cb, void* ctx);

#endif
```

**csv_stream.c:**
```c
#include <stdlib.h>
#include "csv_stream.h"

int csv_stream(const char* path, csv_stream_callback cb, void* ctx) {
    // Simulated: in real implementation, parse CSV and call callback with JSON chunks
    const char* json1 = "{\"row\":1}";
    const char* json2 = "{\"row\":2}";

    cb(json1, 8, 0, ctx);  // 0 = success
    cb(json2, 8, 0, ctx);
    cb(NULL, 0, 0, ctx);   // signal completion

    return 0;
}
```

**csv_stream.go:**
```go
package main

/*
#cgo CFLAGS: -I.
#cgo LDFLAGS: -L. -lcsvstream
#include "csv_stream.h"
#include <stdlib.h>

typedef int (*csv_stream_callback)(const char*, size_t, int, void*);
*/
import "C"
import (
    "fmt"
    "sync"
    "unsafe"
)

type streamContext struct {
    dataCh  chan string
    errCh   chan error
    mu      sync.Mutex
    active  bool
}

//export csvCallback
func csvCallback(json *C.char, length C.size_t, status C.int, ctx unsafe.Pointer) {
    sc := (*streamContext)(ctx)
    sc.mu.Lock()
    defer sc.mu.Unlock()

    if !sc.active {
        return
    }

    if status != 0 {
        sc.errCh <- fmt.Errorf("stream error: status=%d", status)
        return
    }

    if json == nil {
        close(sc.dataCh)
        sc.active = false
        return
    }

    goStr := C.GoStringN(json, C.int(length))
    C.free(unsafe.Pointer(json))
    sc.dataCh <- goStr
}

func StartCSVStream(path string) (<-chan string, <-chan error) {
    dataCh := make(chan string, 10)
    errCh := make(chan error, 1)

    ctx := &streamContext{
        dataCh: dataCh,
        errCh:  errCh,
        active: true,
    }

    go func() {
        cPath := C.CString(path)
        defer C.free(unsafe.Pointer(cPath))

        C.csv_stream(cPath, C.csv_stream_callback(C.csvCallback), unsafe.Pointer(ctx))

        ctx.mu.Lock()
        if ctx.active {
            close(errCh)
        }
        ctx.mu.Unlock()
    }()

    return dataCh, errCh
}

func main() {
    dataCh1, errCh1 := StartCSVStream("file1.csv")
    dataCh2, errCh2 := StartCSVStream("file2.csv")

    var wg sync.WaitGroup
    wg.Add(2)

    go func() {
        defer wg.Done()
        for json := range dataCh1 {
            fmt.Println("File1:", json)
        }
        for err := range errCh1 {
            fmt.Println("File1 Error:", err)
        }
    }()

    go func() {
        defer wg.Done()
        for json := range dataCh2 {
            fmt.Println("File2:", json)
        }
        for err := range errCh2 {
            fmt.Println("File2 Error:", err)
        }
    }()

    wg.Wait()
}
```

